        """.replace("{{fecha_hora}}", java.time.LocalDateTime.now().toString())
                .replace("{{dispositivo}}", "Navegador Web (detalles no disponibles)"); // Aquí podrías integrar una librería para detectar el user agent real
        emailOrchestratorService.sendManageEmail("USERS",mainUser.getUuid(),mainUser.getEmail(), "Nuevo inicio de sesión en tu cuenta de TE ENCONTRÉ", htmlContent);


        return generateAndSaveTokens(auth, mainUser.getUsername());
    }

    /**
     * 3. LOGOUT (EL ANIQUILADOR)
     * Invalida la sesión actual eliminando los tokens de Redis.
     */
    public void logout(String userName) {
        log.info("Cerrando sesión para: {}", userName);
        redisAuthService.deleteAllUserSessions(userName);
    }

    /**
     * 4. REFRESH TOKEN
     * Renueva el Access Token validando que la sesión siga viva en Redis.
     */
    public AuthResponseDTO refreshToken(RefreshTokenRequestDTO request) {
        String refreshToken = request.getRefreshToken();

        // 1. Validar firma y expiración básica del Refresh Token
        if (!jwtUtil.isTokenValid(refreshToken)) {
            throw new JwtException("El Refresh Token ha expirado o es inválido.");
        }

        // Extraemos el userName (que configuramos como el subject en JwtUtil)
        String userName = jwtUtil.extractUsername(refreshToken);

        // 2. VALIDACIÓN CRÍTICA CONTRA REDIS (El Aniquilador)
        String savedRefreshToken = redisAuthService.getRefreshToken(userName);

        if (savedRefreshToken == null || !savedRefreshToken.equals(refreshToken)) {
            log.warn(">>> Intento de refresh con token aniquilado o inexistente para: {}", userName);
            throw new RuntimeException("La sesión ha expirado o ha sido cerrada. Inicie sesión de nuevo.");
        }

        // 3. Generamos el nuevo Access Token con datos frescos de la BD
        MainUser mainUser = (MainUser) userDetailsService.loadUserByUsername(userName);

        Authentication auth = new UsernamePasswordAuthenticationToken(
                mainUser, null, mainUser.getAuthorities()
        );

        String newAccessToken = jwtUtil.generateToken(auth);

        // 4. Actualizamos SOLO el Access Token en Redis (El Refresh se mantiene igual hasta que expire)
        redisAuthService.saveTokenInRedis(
                userName,
                newAccessToken,
                jwtUtil.getExpirationTime(newAccessToken),
                false
        );

        String fullName = userName;
        DniResponse.DatosDni datos = dniService.obtenerDatosDni(userName);
        if (datos != null) {
            fullName = datos.getNombres() + " " + datos.getApellidoPaterno() + " " + datos.getApellidoMaterno();
        }

        // Devolvemos el nuevo par de tokens
        return new AuthResponseDTO(newAccessToken, refreshToken, fullName);
    }

    /**
     * Mtodo auxiliar privado para no repetir la lgica de generacin y guardado en Redis
     */
    private AuthResponseDTO generateAndSaveTokens(Authentication auth, String userName) {
        String accessToken = jwtUtil.generateToken(auth);
        String refreshToken = jwtUtil.generateRefreshToken(auth);

        // Guardamos Access Token
        redisAuthService.saveTokenInRedis(
                userName,
                accessToken,
                jwtUtil.getExpirationTime(accessToken),
                false
        );

        // Guardamos Refresh Token
        redisAuthService.saveTokenInRedis(
                userName,
                refreshToken,
                jwtUtil.getExpirationTime(refreshToken),
                true
        );

        String fullName = userName;
        DniResponse.DatosDni datos = dniService.obtenerDatosDni(userName);
        if (datos != null) {
            fullName = datos.getNombres() + " " + datos.getApellidoPaterno() + " " + datos.getApellidoMaterno();
        }

        return new AuthResponseDTO(accessToken, refreshToken, fullName);
    }
}

import { createContext, useContext, useState, useEffect } from 'react';
import { api } from '../lib/api';

const AUTH_STORAGE_KEY = 'qr-utp.simulated-session';

const readStoredSession = () => {
  try {
    const raw = window.localStorage.getItem(AUTH_STORAGE_KEY);
    if (!raw) return null;

    const parsed = JSON.parse(raw);
    if (!parsed || !parsed.fullName || !parsed.email) return null;

    return { fullName: parsed.fullName, email: parsed.email };
  } catch {
    return null;
  }
};

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [sessionUser, setSessionUser] = useState(() => {
    if (typeof window === 'undefined') return null;
    return readStoredSession();
  });

  const [isLoading, setIsLoading] = useState(false);

  const startSession = (userData, accessToken, refreshToken) => {
    const payload = { fullName: userData.fullName, email: userData.email };
    if (accessToken) {
      payload.accessToken = accessToken;
    }
    if (refreshToken) {
      payload.refreshToken = refreshToken;
    }
    window.localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(payload));
    setSessionUser(payload);
  };

  const login = async ({ dni, passwordHash }) => {
    setIsLoading(true);
    try {
      const response = await api.post('/api/auth/login', { dni, passwordHash });
      const { fullName, accessToken, refreshToken } = response.data;
      startSession({ fullName, email: response.data.email }, accessToken, refreshToken);
      return { ok: true };
    } catch (error) {
      const message = error.response?.data?.message || 'Error al iniciar sesión';
      return { ok: false, error: message };
    } finally {
      setIsLoading(false);
    }
  };

  const register = async ({ dni, email, passwordHash, confirmPasswordHash }) => {
    setIsLoading(true);
    try {
      const response = await api.post('/api/auth/register', { 
        dni, 
        email, 
        passwordHash,
        confirmPasswordHash
      });
      const { fullName, accessToken, refreshToken } = response.data;
      startSession({ fullName, email }, accessToken, refreshToken);
      return { ok: true };
    } catch (error) {
      const message = error.response?.data?.message || 'Error al registrar';
      return { ok: false, error: message };
    } finally {
      setIsLoading(false);
    }
  };

  const logout = async () => {
    try {
      await api.post('/api/auth/logout');
    } catch {
      // Ignore errors - logout locally anyway
    }
    window.localStorage.removeItem(AUTH_STORAGE_KEY);
    setSessionUser(null);
  };

  const refreshToken = async () => {
    const stored = readStoredSession();
    if (!stored?.refreshToken) return false;

    try {
      const response = await api.post('/api/auth/refresh', { refreshToken: stored.refreshToken });
      const { fullName, accessToken, refreshToken: newRefreshToken } = response.data;
      startSession({ fullName, email: stored.email }, accessToken, newRefreshToken);
      return true;
    } catch {
      // Refresh failed, logout
      logout();
      return false;
    }
  };

  useEffect(() => {
    const handleRefresh = (e) => setSessionUser(e.detail);
    window.addEventListener('auth:refresh', handleRefresh);
    return () => window.removeEventListener('auth:refresh', handleRefresh);
  }, []);

  return (
    <AuthContext.Provider value={{ sessionUser, login, register, logout, refreshToken, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import { createContext, useContext, useState, useEffect } from 'react';
import { api } from '../lib/api';

const AUTH_STORAGE_KEY = 'qr-utp.simulated-session';

const readStoredSession = () => {
  try {
    const raw = window.localStorage.getItem(AUTH_STORAGE_KEY);
    if (!raw) return null;

    const parsed = JSON.parse(raw);
    if (!parsed || !parsed.accessToken) return null;

    // Decode JWT payload to get user identity (DNI in subject)
    const tokenPayload = JSON.parse(atob(parsed.accessToken.split('.')[1]));
    const dni = tokenPayload.sub;

    return { fullName: parsed.fullName || dni || 'Usuario', email: parsed.email, accessToken: parsed.accessToken, refreshToken: parsed.refreshToken };
  } catch {
    return null;
  }
};

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [sessionUser, setSessionUser] = useState(() => {
    if (typeof window === 'undefined') return null;
    return readStoredSession();
  });

  const [isLoading, setIsLoading] = useState(false);

  const startSession = (userData, accessToken, refreshToken) => {
    let nameToSave = userData.fullName || userData.dni;

    // Fallback to extract DNI from access token if neither fullName nor DNI was provided
    if (!nameToSave && accessToken) {
      try {
        const payload = JSON.parse(atob(accessToken.split('.')[1]));
        if (payload && payload.sub) {
          nameToSave = payload.sub;
        }
      } catch {
        // Ignorar
      }
    }

    const payload = {
      fullName: nameToSave || 'Usuario',
      email: userData.email || ''
    };

    if (accessToken) {
      payload.accessToken = accessToken;
    }
    if (refreshToken) {
      payload.refreshToken = refreshToken;
    }
    window.localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(payload));
    setSessionUser(payload);
  };

  const login = async ({ dni, passwordHash }) => {
    setIsLoading(true);
    try {
      const response = await api.post('/api/auth/login', { dni, passwordHash });
      const { accessToken, refreshToken, fullName } = response.data;
      startSession({ fullName, email: response.data.email }, accessToken, refreshToken);
      return { ok: true };
    } catch (error) {
      const message = error.response?.data?.message || 'Error al iniciar sesión';
      return { ok: false, error: message };
    } finally {
      setIsLoading(false);
    }
  };

  const register = async ({ dni, email, passwordHash, confirmPasswordHash }) => {
    setIsLoading(true);
    try {
      const response = await api.post('/api/auth/register', { 
        dni, 
        email, 
        passwordHash,
        confirmPasswordHash
      });
      const { accessToken, refreshToken, fullName } = response.data;
      startSession({ fullName, email }, accessToken, refreshToken);
      return { ok: true };
    } catch (error) {
      const message = error.response?.data?.message || 'Error al registrar';
      return { ok: false, error: message };
    } finally {
      setIsLoading(false);
    }
  };

  const logout = async () => {
    try {
      await api.post('/api/auth/logout');
    } catch {
      // Ignore errors - logout locally anyway
    }
    window.localStorage.removeItem(AUTH_STORAGE_KEY);
    setSessionUser(null);
  };

  const refreshToken = async () => {
    const stored = readStoredSession();
    if (!stored?.refreshToken) return false;

    try {
      const response = await api.post('/api/auth/refresh', { refreshToken: stored.refreshToken });
      const { accessToken, refreshToken: newRefreshToken } = response.data;
      startSession({ fullName: stored.fullName, email: stored.email }, accessToken, newRefreshToken);
      return true;
    } catch {
      // Refresh failed, logout
      logout();
      return false;
    }
  };

  useEffect(() => {
    const handleRefresh = (e) => setSessionUser(e.detail);
    window.addEventListener('auth:refresh', handleRefresh);
    return () => window.removeEventListener('auth:refresh', handleRefresh);
  }, []);

  return (
    <AuthContext.Provider value={{ sessionUser, login, register, logout, refreshToken, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import axios from 'axios';

const API_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8080';
const AUTH_STORAGE_KEY = 'qr-utp.simulated-session';

export const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Interceptor para agregar el token JWT a todas las requests
api.interceptors.request.use(
  (config) => {
    try {
      const stored = window.localStorage.getItem(AUTH_STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed.accessToken) {
          config.headers.Authorization = `Bearer ${parsed.accessToken}`;
        }
      }
    } catch {
      // Ignore
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Flag para prevenir loops de refresh
let isRefreshing = false;

// Interceptor para manejar 401/403 y auto-refresh
api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    // Si es 401 y no es una petition de refresh y no we've retryado
    if (error.response?.status === 401 && !originalRequest._retry) {
      // Evitar double refresh
      if (isRefreshing) return Promise.reject(error);

      originalRequest._retry = true;
      isRefreshing = true;

      try {
        const stored = window.localStorage.getItem(AUTH_STORAGE_KEY);
        if (!stored) {
          throw new Error('No session');
        }

        const parsed = JSON.parse(stored);
        if (!parsed.refreshToken) {
          throw new Error('No refresh token');
        }

        // Llamar al endpoint de refresh
        const response = await axios.post(`${API_URL}/api/auth/refresh`, {
          refreshToken: parsed.refreshToken,
        });

        const { fullName, accessToken, refreshToken: newRefreshToken } = response.data;

  // Guardar nuevos tokens
  const newSession = { fullName: parsed.fullName, email: parsed.email, accessToken, refreshToken: newRefreshToken };
  window.localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(newSession));

  // Emitir evento para actualizar el AuthContext
  window.dispatchEvent(new CustomEvent('auth:refresh', { detail: newSession }));

        // Reintentar request original
        originalRequest.headers.Authorization = `Bearer ${accessToken}`;
        isRefreshing = false;
        return api(originalRequest);
      } catch (refreshError) {
        isRefreshing = false;
        // Refresh falló - logout
        window.localStorage.removeItem(AUTH_STORAGE_KEY);
        window.location.href = '/login';
        return Promise.reject(error);
      }
    }

    // Otros errores (no 401) o ya se retryó
    return Promise.reject(error);
  }
);

export default api;

